#!/usr/bin/env node
// Seeds The Focus Tax, the members-only essay series, into Firestore:
//   - reads/the-focus-tax              public: series title, description and
//                                      the archive list (no essay text)
//   - reads/the-focus-tax/essays/{slug} members only: the full essay HTML
//
// The public pages at /reads and /reads/<slug> are static files generated by
// build-reads.js from the same markdown; they carry each essay's opening, and
// public/js/reads-page.js swaps in the full text from here for a signed-in
// member (or from the claimRead function for a reader who signs up inline).
//
// The series used to be a course (courses/the-focus-tax, with modules and an
// Enroll step). That record is retired here: its status is set to inactive,
// which takes it off every course surface. Its modules are left in place.
//
// Safe to re-run, and re-running is how edited copy gets picked up. The
// Seed The Focus Tax workflow runs it on every push to main that touches the
// essays, so nobody needs to run it by hand.
//
// To run by hand: Admin credentials, from scripts/ after `npm install`:
//   node seed-focus-tax.js
// See scripts/README.md for the two ways to authenticate.

const { initAdmin, assertCredentials } = require('./lib/init');
const { SERIES, loadSeries } = require('./lib/essays');

const LEGACY_COURSE = 'the-focus-tax';

async function main() {
  const { essays } = loadSeries();
  const { admin, db, projectId } = initAdmin();
  console.log(`Project: ${projectId}`);
  await assertCredentials(db, projectId);
  const now = admin.firestore.FieldValue.serverTimestamp();

  const seriesRef = db.collection('reads').doc(SERIES.slug);
  await seriesRef.set({
    title: SERIES.title,
    tagline: SERIES.tagline,
    description: SERIES.description,
    author: SERIES.author,
    essays: essays.map((e) => ({
      issue: e.issue, slug: e.slug, title: e.title, hook: e.hook,
      readTime: e.readTime, words: e.words, date: e.date
    })),
    updatedAt: now
  }, { merge: true });

  for (const e of essays) {
    await seriesRef.collection('essays').doc(e.slug).set({
      issue: e.issue,
      slug: e.slug,
      title: e.title,
      hook: e.hook,
      readTime: e.readTime,
      words: e.words,
      html: e.html.trim(),
      updatedAt: now
    });
    console.log(`Focus Tax ${e.issueLabel} seeded: ${e.title} (${e.words} words)`);
  }

  // Essays that were removed from the folder come off the site too.
  const current = new Set(essays.map((e) => e.slug));
  const stored = await seriesRef.collection('essays').get();
  for (const d of stored.docs) {
    if (!current.has(d.id)) {
      await d.ref.delete();
      console.log(`Removed essay no longer in the folder: ${d.id}`);
    }
  }

  const legacyRef = db.collection('courses').doc(LEGACY_COURSE);
  const legacy = await legacyRef.get();
  if (legacy.exists && legacy.data().status !== 'inactive') {
    await legacyRef.set({ status: 'inactive', updatedAt: now }, { merge: true });
    console.log('Retired the old Focus Tax course: status set to inactive.');
  }

  console.log(`\nSeeded ${essays.length} essays. Read them at /reads.`);
}

if (require.main === module) {
  main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
}
